argv:
$ErrorActionPreference='Stop'
function J([string]$u,[int]$t=20){Invoke-RestMethod -Uri $u -Method Get -TimeoutSec $t}
$base='http://127.0.0.1:17448'
$watch=J ($base+'/api/supervisor-watchdog?detect=0') 8
$exact=J ($base+'/api/supervisor-watchdog/multiagent-exactid-snapshot') 25
$chats=J ($base+'/api/supervisor-watchdog/managed-chats?inspect=1') 25
$life=J ($base+'/api/operator-lifecycle') 8
$wanted='(?i)(creator|media|growth|native|qa|bridge)'
$chatRows=@($chats.chats|Where-Object {([string]$_.role+' '+[string]$_.name+' '+[string]$_.id) -match $wanted}|ForEach-Object {
 [ordered]@{id=$_.id;name=$_.name;role=$_.role;url=$_.url;repository=$_.repository;branch=$_.branch;status=$_.status;openTabs=$_.openTabs;highMode=$_.highMode;generating=$_.generating;draftPresent=$_.draftPresent;contextLimit=$_.contextLimit;profileName=$_.profileName;latestAssignmentState=$_.latestAssignment.state}
})
$exactRows=@($exact.rows|Where-Object {([string]$_.role+' '+[string]$_.managedChatId) -match $wanted}|ForEach-Object {
 [ordered]@{role=$_.role;managedChatId=$_.managedChatId;expectedConversationId=$_.expectedConversationId;identityState=$_.identityState;observedExactTargetCount=$_.observedExactTargetCount;canonicalUrl=$_.observedExactTarget.canonicalUrl;generationState=$_.generationState;draftState=$_.draftState;branchStatus=$_.branchStatus;lastAssignmentState=$_.lastAssignmentState;error=$_.error}
})
[ordered]@{
 object='owner.r44.live_bindings.v1'
 checkedAt=(Get-Date).ToUniversalTime().ToString('o')
 autonomy=[ordered]@{enabled=$watch.config.enabled;mode=$watch.config.mode;allowAutonomousSend=$watch.config.allowAutonomousSend;enforceHighMode=$watch.config.enforceHighMode;highModeStrategy=$watch.config.highModeStrategy;migrationEnabled=$watch.config.migrationEnabled;autoContinueEnabled=$watch.config.autoContinueEnabled;sendProtectedDraftEnabled=$watch.config.sendProtectedDraftEnabled}
 lifecycle=$life
 chats=$chatRows
 exact=$exactRows
 providerMutationPerformed=$false
 chatDeletionPerformed=$false
}|ConvertTo-Json -Depth 20 -Compress
